import { registerScript, ABrain, ContinueReduceBloodEffect } from "../../runtime.js";

export class FiveHardThirdNpc extends ABrain {
  m_attackTurn = 0;
  m_targer = null;
  deadEffect = null;
  m_bloodReduce = 400;
  OnBeginSelfTurn() {
            super.OnBeginSelfTurn();
        }
  OnBeginNewTurn() {
            super.OnBeginNewTurn();
            this.m_body.CurrentDamagePlus = 1;
            this.m_body.CurrentShootMinus = 1;

            if (this.deadEffect != null)
                this.Game.RemovePhysicalObj(this.deadEffect, true);
            this.deadEffect = null;

            if (this.m_targer != null)
                this.m_targer.SpeedMultX(3);
        }
  OnCreated() {
            super.OnCreated();
        }
  OnStartAttacking() {
            super.OnStartAttacking();
            this.FindTarget();
        }
  FindTarget() {
            let minXLeft = 2147483647;
            let minXRight = -2147483648;
            let pLeft = null;
            let pRight = null;

            for (const player of this.Game.GetAllLivingPlayers())
            {
                if (player.X > 1000 && player.X > minXRight)
                {
                    minXRight = player.X;
                    pRight = player;
                }
                else if (player.X <= 1000 && player.X < minXLeft)
                {
                    minXLeft = player.X;
                    pLeft = player;
                }
            }

            if (pLeft == null && pRight != null)
                this.m_targer = pRight;
            else if (pRight == null && pLeft != null)
                this.m_targer = pLeft;
            else if (pRight != null && pLeft != null)
            {
                // find target near
                let disToLeft = this.Body.Distance(pLeft.X, pLeft.Y);
                let disToRight = this.Body.Distance(pRight.X, pRight.Y);

                if (disToLeft < disToRight)
                    this.m_targer = pLeft;
                else
                    this.m_targer = pRight;
            }
            else
            {
                this.m_targer = this.Game.FindRandomPlayer();
            }

            this.MoveAndAttack();
        }
  MoveAndAttack() {
            if (this.m_targer != null)
            {
                this.Body.MoveTo(this.m_targer.X, this.m_targer.Y, "fly", 1000, this.AttackTarget.bind(this), 6);
            }
        }
  AttackTarget() {
            this.Body.MaxBeatDis = 500;
            this.m_targer.SpeedMultX(18);
            this.Body.PlayMovie("beatA", 500, 0);
            //Body.Beat(m_targer, "beatA", 100, 0, 500);
            this.Body.CallFuction(this.CreateDeadEffect.bind(this), 1500);
            this.Body.BeatDirect(this.m_targer, "", 1600, 1, 1);
            this.Body.CallFuction((this.StartMoveTarget.bind(this)), 1700);
            this.m_targer.AddEffect(new ContinueReduceBloodEffect(1, this.m_bloodReduce, this.Body), 3200);
            this.Body.CallFuction(this.MoveToUp.bind(this), 2500);
        }
  MoveToUp() {
            this.Body.MoveTo(this.Body.X, this.Body.Y - 50, "fly", 0, 6);
        }
  StartMoveTarget() {
            if (this.m_targer.X > 1000)
            {
                // chay ve ben phai
                this.m_targer.StartSpeedMult(this.m_targer.X + 150, this.m_targer.Y, 0);
            }
            else
            {
                // chay ve ben trai
                this.m_targer.StartSpeedMult(this.m_targer.X - 150, this.m_targer.Y, 0);
            }
        }
  CreateDeadEffect() {
            this.deadEffect = ((this.Game)).Createlayer(this.m_targer.X, this.m_targer.Y, "", "asset.game.4.tang", "", 1, 1);
        }
  OnDie() {
            super.OnDie();
            this.Body.Die(2500);
            this.Body.PlayMovie("die", 1200, 0);
        }
  OnStopAttacking() {
            super.OnStopAttacking();
        }
}
